public enum CircuitState { Closed, Open, HalfOpen }

public interface ICircuitBreaker
{
    CircuitState State { get; }
    Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct);
}

public sealed class CircuitOpenException() : InvalidOperationException("Circuit is open");

public sealed class CircuitBreaker : ICircuitBreaker
{
    private readonly object _sync = new();
    private readonly int _failureThreshold;
    private readonly TimeSpan _openDuration;
    private readonly TimeProvider _time;
    private int _failures;
    private DateTimeOffset _openedAt;
    private bool _probeInFlight;
    private CircuitState _state = CircuitState.Closed;

    public CircuitBreaker(int failureThreshold, TimeSpan openDuration, TimeProvider? time = null)
    {
        if (failureThreshold <= 0) throw new ArgumentOutOfRangeException(nameof(failureThreshold));
        _failureThreshold = failureThreshold;
        _openDuration = openDuration;
        _time = time ?? TimeProvider.System;
    }

    public CircuitState State { get { lock (_sync) return _state; } }

    public async Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct)
    {
        var isProbe = EnterIsProbe();
        try
        {
            var result = await action(ct).ConfigureAwait(false);
            OnSuccess();
            return result;
        }
        catch (OperationCanceledException)
        {
            if (isProbe) ReleaseProbe();
            throw;
        }
        catch
        {
            OnFailure();
            throw;
        }
    }

    private bool EnterIsProbe()
    {
        lock (_sync)
        {
            if (_state == CircuitState.Open)
            {
                if (_time.GetUtcNow() - _openedAt < _openDuration) throw new CircuitOpenException();
                _state = CircuitState.HalfOpen;
            }
            if (_state == CircuitState.HalfOpen)
            {
                if (_probeInFlight) throw new CircuitOpenException();
                _probeInFlight = true;
                return true;
            }
            return false;
        }
    }

    private void OnSuccess()
    {
        lock (_sync)
        {
            _failures = 0;
            _probeInFlight = false;
            _state = CircuitState.Closed;
        }
    }

    private void OnFailure()
    {
        lock (_sync)
        {
            _failures++;
            if (_state == CircuitState.HalfOpen || _failures >= _failureThreshold)
            {
                _state = CircuitState.Open;
                _openedAt = _time.GetUtcNow();
                _probeInFlight = false;
            }
        }
    }

    private void ReleaseProbe()
    {
        lock (_sync) { _probeInFlight = false; }
    }
}
